// Personalize subject and content with recipient data
const items = $input.all();
const results = [];

for (const item of items) {
  let subject = item.json.subject || '';
  let content = item.json.content || '';

  const recipientData = item.json.recipientData || {};

  // Replace placeholders in subject
  subject = subject
    .replace(/\{\{firstName\}\}/gi, recipientData.firstName || 'there')
    .replace(/\{\{lastName\}\}/gi, recipientData.lastName || '')
    .replace(/\{\{company\}\}/gi, recipientData.companyName || 'your company')
    .replace(/\{\{companyName\}\}/gi, recipientData.companyName || 'your company')
    .replace(/\{\{domain\}\}/gi, recipientData.domain || '')
    .replace(/\{\{designation\}\}/gi, recipientData.designation || '')
    .trim();

  // Replace placeholders in content
  content = content
    .replace(/\{\{firstName\}\}/gi, recipientData.firstName || 'there')
    .replace(/\{\{lastName\}\}/gi, recipientData.lastName || '')
    .replace(/\{\{company\}\}/gi, recipientData.companyName || 'your company')
    .replace(/\{\{companyName\}\}/gi, recipientData.companyName || 'your company')
    .replace(/\{\{domain\}\}/gi, recipientData.domain || '')
    .replace(/\{\{designation\}\}/gi, recipientData.designation || '');

  results.push({
    json: {
      ...item.json,
      subject: subject,
      content: content,
      recipientData: recipientData
    }
  });
}

return results;

// Extract text from Gemini response
const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const response = items[i].json;
  const previousData = $('Replace Placeholders (Immediate)').all()[i].json;

  let personalizedText = '';

  if (response.content && response.content.parts && response.content.parts.length > 0) {
    personalizedText = response.content.parts[0].text;
  } else if (response.text) {
    personalizedText = response.text;
  } else if (typeof response === 'string') {
    personalizedText = response;
  } else {
    personalizedText = previousData.content;
  }

  personalizedText = personalizedText.trim();

  results.push({
    json: {
      personalizedContent: personalizedText,
      email: previousData.email,
      subject: previousData.subject
    }
  });
}

return results;

